{
  "spans": [
    {
      "label": "QUOTE",
      "frame": "ཟ་མ་ཏོག་བཀོད་པའི་མདོར།",
      "head": "འཕགས་པ་འཇིག་རྟེན་",
      "tail": "བཀོད་པར་བཤད་པའི་ཕྱིར་དང་།"
    },
    {
      "label": "QUOTE",
      "frame": "ལྷའི་བུ་རབ་གནས་ཀྱི་མདོར།",
      "head": "འདོད་གཟུགས་ཀྱི་",
      "tail": "གསུངས་པའི་ཕྱིར།"
    },
    {
      "label": "QUOTE",
      "frame": "མཛོད་ལས།",
      "head": "རྫུ་འཕྲུལ་གཞན་བརྟེན་མ་གཏོགས་པ། །དེ་དག་གོང་མ་མཐོང་བ་མེད། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རྒྱན་ལས་བཤད་པའི་ཕྱིར་ཏེ།",
      "head": "བསམ་གཏན་བཞི་པ་ཤིན་ཏུ་དག་ཐོབ་ནས། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "བཤད་པའི་ཕྱིར་ཞེ་ན།",
      "head": "མི་རྟག་ཡེ་ཤེས་ཡོངས་སུ་གཟུང་བ་དང་། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "ཀུན་བཏུས་ལས།",
      "head": "མཐོང་བའི་ལམ་གང་ཞེ་ན། མདོར་བསྡུ་ན་འཇིག་རྟེན་པའི་ཆོས་མཆོག་གི་མཇུག་ཐོག་ཏུ་མི་དམིགས་པའི་ཏིང་ངེ་འཛིན་ཤེས་རབ་མཚུངས་ལྡན་དང་བཅས་པ་སྟེ་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "ཀུན་བཏུས་ལས་",
      "head": "གཟུང་བ་རྟོགས་པ་དང་། འཛིན་པ་རྟོགས་པ་གཉིས་སུ་གསུངས་ཤིང་།",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "མདོ་ལས།",
      "head": "ཆོས་རྣམས་ལ་ཆོས་ཀྱི་མིག་རྡུལ་མེད་ཅིང་དྲི་མ་དང་བྲལ་བ་རྣམ་པར་དག་པ་སྐྱེས་སོ་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "མདོ་ལས།",
      "head": "ཆོས་མཐོང་བ། ཆོས་ཐོབ་པ། ཆོས་རིག་པ། ཆོས་རྟོགས་པ། སོམ་ཉི་ལས་བརྒལ་བ། ཐེ་ཚོམ་ལས་བརྒལ་བ། གཞན་གྱི་དྲིང་མི་འཇོག་པ། སྟོན་པའི་བསྟན་པ་ལས་གཞན་གྱིས་དཀྲིར་མི་བཏུབ་པའོ་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "གསུངས་པའི་ཕྱིར།",
      "head": "དྲུག་ཚན་དྲུག་གི་རྣམ་པ་སུམ་ཅུ་རྩ་དྲུག་ཅན་སྐྱེས་པ་གང་ཡིན་པ་དེ་ནི་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "གསུངས་པའི་ཕྱིར་རོ། །",
      "head": "དེ་དག་སྤོང་བ་ཉིད་དུ་གཉེན་པོ་རྣམ་པ་བཞི་ཡང་དེ་བཞིན་དུ་དབྱེ་བས་ཐ་དད་དོ་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རིག་པ་དྲུག་ཅུ་པར།",
      "head": "ཆོས་ཤེས་པ་ཡི་འོག་ཏུ་ནི། །འདི་ལ་བྱེ་བྲག་དབྱེར་ཡོད་ན། །ཤིན་ཏུ་ཕྲ་བའི་དངོས་རྣམས་ལ། །གང་གིས་སྐྱེ་བར་རྣམ་བརྟགས་པ། །རྣམ་པར་མི་མཁས་དེ་ཡིས་ནི། །རྐྱེན་ལས་བྱུང་བའི་དོན་མ་མཐོང་། །",
      "tail": ""
    }
  ]
}
